insert into public.site_content (content_key, data)
values
  ('profil', '{"nama_desa":"Desa Timpik","kecamatan":"Kecamatan Susukan","kabupaten":"Kabupaten Semarang","provinsi":"Jawa Tengah","kode_pos":"50774","alamat_kantor":"Jl. Raya Balai Desa Timpik, Kec. Susukan, Kab. Semarang, Jawa Tengah 50774","telepon":"6285166439180","email":"desatimpik.susukan@gmail.com","jam_layanan":"Senin - Kamis: 08.00 - 15.00 WIB | Jumat: 08.00 - 11.30 WIB","foto_struktur":"/images/struktur-organisasi-timpik.jpg","visi":"Terwujudnya Desa Timpik yang Maju, Sejahtera, Mandiri Berbasis Pertanian Berkelanjutan dan Berkeadaban Budaya Adiluhung.","misi":["Meningkatkan kualitas pelayanan administrasi publik yang cepat, transparan, dan terpercaya bagi seluruh warga.","Mengembangkan perekonomian desa berbasis sektor agraris modern dan penguatan ketahanan pangan lokal.","Melestarikan dan mempromosikan kekayaan seni budaya tradisional seperti Wayang Orang, Karawitan, dan Angguk.","Mewujudkan tata kelola pemerintahan desa yang bersih, akuntabel, dan bebas dari korupsi.","Meningkatkan kualitas infrastruktur pertanian, irigasi, dan aksesibilitas fasilitas publik masyarakat."],"dusun":[{"id":"bogo","nama":"Dusun Bogo","panggilan":"Bogo","deskripsi":"Sentra kesenian Wayang Orang (Badoyo), tradisi budaya adiluhung, dan hamparan sawah subur P3A Bogo Wastro.","kepala_dusun":"Bapak Kadus Bogo","potensi_utama":"Wayang Orang, Pertanian Padi, Karawitan","jumlah_rt":"4 RT / 1 RW","luas":"68 Ha"},{"id":"sumber","nama":"Dusun Sumber","panggilan":"Sumber","deskripsi":"Pusat kesenian bernafas religi Angguk Alhidayah, sumber mata air alami pengairan desa, dan kerukunan warga.","kepala_dusun":"Bapak Kadus Sumber","potensi_utama":"Seni Angguk, Konservasi Mata Air, Palawija","jumlah_rt":"3 RT / 1 RW","luas":"54 Ha"},{"id":"krajan","nama":"Dusun Timpik Krajan","panggilan":"Krajan","deskripsi":"Pusat tata kelola pemerintahan desa, kantor Balai Desa, pendopo pertemuan, dan perpustakaan desa Sumber Ilmu.","kepala_dusun":"Bapak Kadus Krajan","potensi_utama":"Pelayanan Publik, Balai Desa, UMKM Perdagangan","jumlah_rt":"5 RT / 2 RW","luas":"61 Ha"},{"id":"kencana","nama":"Dusun Kencana","panggilan":"Kencana","deskripsi":"Kawasan lumbung pangan masyarakat mandiri LPM Putri Kencana, pembibitan tani modern, dan persawahan terpadu.","kepala_dusun":"Bapak Kadus Kencana","potensi_utama":"Lumbung Pangan Padi, Gapoktan, Peternakan","jumlah_rt":"4 RT / 1 RW","luas":"60 Ha"}],"statistik":{"total_penduduk":"5.696 Jiwa","total_kk":"872 KK","luas_wilayah":"243 Ha","lahan_pertanian":"189 Ha (78%)","laki_laki":"2.848 Jiwa","perempuan":"2.848 Jiwa","pekerjaan_petani":"76%","pekerjaan_wiraswasta":"14%","pekerjaan_lainnya":"10%"},"transparansi_apbdes":{"tahun":"2026","total_pendapatan":"Rp 1.428.560.000","dana_desa":"Rp 812.450.000","alokasi_dana_desa":"Rp 415.800.000","pad_desa":"Rp 98.310.000","lain_lain":"Rp 102.000.000","belanja_pembangunan":"Rp 684.200.000","belanja_pemerintahan":"Rp 395.100.000","pemberdayaan_masyarakat":"Rp 215.000.000","pembinaan_budaya":"Rp 84.260.000","biaya_pelayanan_warga":"Rp 0,- (100% Gratis)"},"sosial_media":{"instagram":"https://instagram.com/desatimpik_official","facebook":"https://facebook.com/desatimpiksusukan","youtube":"https://youtube.com/@DesaTimpikSemarang"}}'::jsonb),
  ('kontak', '{"operasional":{"nama_kantor":"Kantor Balai Desa Timpik","alamat":"Jl. Raya Balai Desa Timpik, Kec. Susukan, Kab. Semarang, Jawa Tengah 50774","telepon":"6285166439180","email":"desatimpik.susukan@gmail.com","jam_senin_kamis":"08.00 - 15.00 WIB","jam_jumat":"08.00 - 11.30 WIB","status_layanan":"Buka Normal","keterangan_layanan":"Pelayanan tatap muka dan permohonan surat online aktif di Balai Desa Timpik","maps_url":"https://maps.google.com/?q=Balai+Desa+Timpik+Susukan+Semarang"},"kontak_darurat":[{"id":"bidan-desa","nama":"Bidan Desa Timpik","instansi":"Poskesdes Desa Timpik","kategori":"Medis & Kesehatan","nomor":"081234567890","tipe_kontak":"whatsapp","ketersediaan":"Aktif 24 Jam","deskripsi":"Penanganan gawat darurat ibu hamil, persalinan, imunisasi, dan pertolongan pertama medis warga desa.","badge_color":"rose"},{"id":"ambulans-desa","nama":"Mobil Siaga / Ambulans Desa","instansi":"Pemerintah Desa Timpik","kategori":"Transportasi Darurat","nomor":"081234567891","tipe_kontak":"whatsapp","ketersediaan":"Siaga di Balai Desa","deskripsi":"Fasilitas rujukan cepat warga yang membutuhkan pengantaran segera ke Puskesmas Susukan atau RSUD terdekat.","badge_color":"rose"},{"id":"babinsa-bhabinkamtibmas","nama":"Babinsa & Bhabinkamtibmas","instansi":"Koramil & Polsek Susukan","kategori":"Keamanan & Kamtibmas","nomor":"081234567892","tipe_kontak":"whatsapp","ketersediaan":"Siaga Wilayah","deskripsi":"Pelaporan gangguan keamanan warga, perselisihan lingkungan, pencurian, pengamanan kegiatan warga, atau bencana alam.","badge_color":"emerald"},{"id":"petugas-air-p3a","nama":"Petugas Pengairan P3A Bogo Wastro","instansi":"P3A Bogo Wastro","kategori":"Pertanian & Irigasi","nomor":"081234567893","tipe_kontak":"whatsapp","ketersediaan":"Hari Kerja & Giliran Air","deskripsi":"Konsultasi jadwal giliran debit air sawah 243 Ha, laporan pintu air tersumbat, atau kendala saluran irigasi persawahan.","badge_color":"teal"},{"id":"puskesmas-susukan","nama":"UGD Puskesmas Susukan","instansi":"Dinas Kesehatan Kab. Semarang","kategori":"Fasilitas Rujukan Medis","nomor":"0298123456","tipe_kontak":"telepon","ketersediaan":"UGD 24 Jam","deskripsi":"Pusat rujukan penanganan medis tingkat pertama Kecamatan Susukan untuk rawat inap darurat dan rujukan spesialis RSUD.","badge_color":"blue"}]}'::jsonb),
  ('berita', '[{"id":"peluncuran-portal-digital-desa-timpik","judul":"Pemerintah Desa Timpik & Tim KKN Resmi Luncurkan Portal Digital dan Layanan Persuratan Online Mandiri","kategori":"Pemerintahan & Pelayanan","tanggal":"08 November 2026","penulis":"Pemerintah Desa Timpik","dusun_id":"krajan","lembaga_id":"ppdi","ringkasan":"Portal resmi Desa Timpik kini memuat layanan pengajuan surat online, transparansi APBDes, dan kalender kegiatan 4 dusun.","konten":"Sebagai wujud komitmen peningkatan kualitas pelayanan publik yang transparan, efisien, dan bebas pungli (Rp 0,-), Pemerintah Desa Timpik bersama rekan-rekan mahasiswa KKN resmi meluncurkan portal sistem informasi dan otomasi pelayanan administrasi persuratan warga desa. Melalui sistem ini, warga dari 4 dusun (Krajan, Sumber, Bogo, Kencana) dapat mengajukan permohonan surat seperti SKU, SKTM, dan pengantar SKCK dari ponsel pintar masing-masing tanpa harus meninggalkan ladang atau pekerjaan mereka. Portal ini juga memuat transparansi APBDes dan kalender agenda kegiatan desa.","gambar":"/images/balai-desa-timpik.jpg","tag":"Inovasi Pelayanan"},{"id":"digitalisasi-surat-kkn","judul":"Mahasiswa KKN Hadirkan Sistem Layanan Otomasi Surat Digital di Desa Timpik","kategori":"Program KKN","tanggal":"07 November 2026","penulis":"Tim KKN Desa Timpik","dusun_id":"krajan","lembaga_id":"ppdi","ringkasan":"Sebagai langkah modernisasi birokrasi dan mempermudah warga mengurus dokumen tanpa antre, mahasiswa KKN bersama Pemdes meluncurkan portal otomasi surat berbasis Google Forms.","konten":"Program kerja ini ditujukan untuk memangkas birokrasi pelayanan di Kantor Balai Desa Timpik. Melalui sistem ini, warga petani dan pedagang dapat mengajukan Surat Keterangan Usaha (SKU), SKTM, dan pengantar SKCK dari ponsel pintar masing-masing tanpa harus meninggalkan ladang atau kesibukan harian. Sistem ini diintegrasikan langsung dengan formulir digital resmi desa guna memastikan data pribadi kependudukan warga tetap terjaga aman.","gambar":"/images/balai-desa-timpik.jpg","tag":"Digitalisasi Desa"},{"id":"musdes-rkpdes-prioritas-pertanian","judul":"Musdes RKPDes 2027: Pemdes & BPD Sepakati Prioritas Pembangunan Saluran Irigasi dan Jalan Usaha Tani","kategori":"Pemerintahan & Pelayanan","tanggal":"05 November 2026","penulis":"BPD & Pemdes Timpik","dusun_id":"krajan","lembaga_id":"bpd","ringkasan":"Musyawarah perencanaan desa menetapkan fokus anggaran APBDes 2027 untuk penguatan infrastruktur pengairan sawah 243 Ha dan rabat beton jalan tani antar-dusun.","konten":"Musyawarah Desa (Musdes) yang diselenggarakan di Pendopo Balai Desa Timpik dihadiri oleh jajaran BPD, Perangkat Desa, para Ketua RT/RW se-Desa Timpik, tokoh masyarakat, dan perwakilan Gapoktan. Dalam forum musyawarah mufakat ini, disepakati bahwa usulan prioritas teratas tahun anggaran mendatang difokuskan pada perbaikan talud saluran primer irigasi persawahan dan rabat beton jalan usaha tani Dusun Bogo dan Sumber guna memangkas ongkos angkut hasil panen petani.","gambar":"/images/kelembagaan-desa-timpik.jpg","tag":"Pembangunan Desa"},{"id":"rembuk-tani-gapoktan","judul":"Rembuk Tani Musim Tanam: GAPOKTAN Putri Kencana & P3A Bogo Wastro Siapkan Pasokan Air","kategori":"Pertanian & Agraris","tanggal":"03 November 2026","penulis":"Pemerintah Desa Timpik","dusun_id":"kencana","lembaga_id":"gapoktan","ringkasan":"Musyawarah bersama para petani di Pendopo Balai Desa menyepakati jadwal penggiliran debit air saluran irigasi dan distribusi pupuk bersubsidi untuk luas sawah 243 Hektar.","konten":"Pertemuan yang dihadiri pengurus Gapoktan Putri Kencana dan P3A Bogo Wastro menghasilkan kesepakatan tata kelola pembagian air yang adil bagi seluruh blok persawahan di Dusun Bogo, Dusun Sumber, dan wilayah hilir. Langkah ini krusial untuk mengantisipasi variasi cuaca dan menjamin target panen raya padi tahun ini tetap optimal bagi kesejahteraan para petani.","gambar":"/images/kelembagaan-desa-timpik.jpg","tag":"Ketahanan Pangan"},{"id":"wayang-orang-badoyo","judul":"Semarak Pagelaran Wayang Orang (Badoyo) Dusun Bogo Pukau Warga dan Wisatawan","kategori":"Kesenian & Budaya","tanggal":"28 Oktober 2026","penulis":"Pokdarwis Desa Timpik","dusun_id":"bogo","lembaga_id":"pokdarwis","ringkasan":"Paguyuban seni tradisional Dusun Bogo mementaskan lakon pewayangan epik Jawa di pelataran Balai Desa Timpik yang dihadiri ratusan penonton lintas generasi.","konten":"Kesenian Wayang Orang Badoyo yang menjadi ikon budaya kebanggaan Desa Timpik kembali tampil memukau dengan iringan gending gamelan karawitan Sekar Melati. Para aktor dan aktris warga asli Dusun Bogo memerankan karakter pewayangan dengan kostum tradisi lengkap, membuktikan dedikasi generasi muda desa dalam menjaga seni tradisi adiluhung agar tidak punah tergerus arus modernisasi.","gambar":"/images/gapura-desa-timpik.jpg","tag":"Pelestarian Budaya"},{"id":"posyandu-kampung-kb","judul":"TP PKK dan Kampung KB Putri Mandiri Gelar Pemeriksaan Balita & Cegah Stunting","kategori":"Kesehatan & Keluarga","tanggal":"22 Oktober 2026","penulis":"TP PKK Desa Timpik","dusun_id":"sumber","lembaga_id":"pkk","ringkasan":"Kegiatan posyandu terpadu meliputi penimbangan berat badan balita, imunisasi dasar, penyuluhan gizi sayur organik, dan pembagian makanan tambahan (PMT) bergizi tinggi.","konten":"Kolaborasi kader posyandu TP PKK bersama bidan desa dan rekan-rekan mahasiswa KKN berlangsung sukses. Program ini berfokus pada pemantauan tumbuh kembang 1000 Hari Pertama Kehidupan (HPK) untuk memastikan Desa Timpik bebas dari risiko stunting melalui optimalisasi bahan pangan pangan lokal yang kaya nutrisi.","gambar":"/images/balai-desa-timpik.jpg","tag":"Kesehatan Masyarakat"}]'::jsonb),
  ('agenda', '[{"id":"agenda-peluncuran-portal","nama":"Sosialisasi & Bimbingan Teknis Portal Layanan Surat Online Mandiri","tanggal":"08 November 2026","waktu":"09.00 - 12.00 WIB","lokasi":"Pendopo Balai Desa Timpik","penyelenggara":"Pemerintah Desa Timpik & Tim KKN","kategori":"Pemerintahan","deskripsi":"Pelatihan tata cara pengajuan surat mandiri online tanpa antre bagi pengurus RT/RW dan perwakilan generasi muda 4 dusun.","peserta":"Perangkat Desa, Ketua RT/RW, Karang Taruna, & Warga Umum"},{"id":"agenda-rembuk-tani-musim-tanam","nama":"Rembuk Tani & Pembagian Giliran Debit Air Musim Tanam II","tanggal":"15 November 2026","waktu":"08.30 - 11.30 WIB","lokasi":"Balai Pertemuan Poktan Putri Kencana, Dusun Kencana","penyelenggara":"P3A Bogo Wastro & GAPOKTAN Putri Kencana","kategori":"Pertanian","deskripsi":"Musyawarah bersama seluruh ketua kelompok tani 4 dusun mengenai jadwal pengaliran saluran sekunder irigasi dan pengajuan alokasi pupuk bersubsidi.","peserta":"Seluruh Petani & Penggarap Sawah Desa Timpik"},{"id":"agenda-posyandu-balita-lansia","nama":"Posyandu Balita & Posbindu Lansia Terpadu Kampung KB","tanggal":"18 November 2026","waktu":"08.00 - 11.00 WIB","lokasi":"Poskesdes Balai Desa Timpik Krajan","penyelenggara":"TP-PKK & Kampung KB Putri Mandiri","kategori":"Kesehatan","deskripsi":"Penimbangan berat badan balita, pengukuran tinggi badan pencegahan stunting, PMT bergizi, cek gula darah, dan tensi gratis bagi lansia.","peserta":"Ibu Hamil, Balita (0-5 th), & Warga Usia Lanjut"},{"id":"agenda-latihan-wayang-badoyo","nama":"Gladi Resik & Latihan Rutin Paguyuban Wayang Orang Badoyo","tanggal":"21 November 2026","waktu":"19.30 - 23.00 WIB","lokasi":"Sanggar Seni Budaya, Dusun Bogo","penyelenggara":"Paguyuban Wayang Orang Badoyo Dusun Bogo","kategori":"Kebudayaan","deskripsi":"Latihan karawitan pengiring dan gladi adegan lakon pewayangan tradisional oleh generasi muda dan sesepuh Dusun Bogo.","peserta":"Warga Dusun Bogo & Terbuka untuk Penonton Umum"},{"id":"agenda-musdes-rkpdes-2027","nama":"Musyawarah Desa (Musdes) Penyusunan RKPDes & Transparansi APBDes","tanggal":"26 November 2026","waktu":"09.00 - 13.00 WIB","lokasi":"Pendopo Balai Desa Timpik","penyelenggara":"BPD & Pemerintah Desa Timpik","kategori":"Pemerintahan","deskripsi":"Penetapan usulan prioritas pembangunan fisik jalan usaha tani, normalisasi drainase, dan alokasi bantuan sosial masyarakat.","peserta":"BPD, LPMD, Ketua RT/RW se-Desa Timpik, & Tokoh Masyarakat"},{"id":"agenda-kerja-bakti-irigasi","nama":"Kerja Bakti Gotong Royong Normalisasi Saluran Irigasi Sawah","tanggal":"02 Desember 2026","waktu":"07.00 - 10.30 WIB","lokasi":"Pintu Air Utama P3A, Dusun Bogo","penyelenggara":"P3A Bogo Wastro & Linmas Desa","kategori":"Pertanian","deskripsi":"Pembersihan endapan lumpur dan sampah gulma pada tanggul sekunder saluran air persawahan 243 Ha sebelum musim tanam raya.","peserta":"Seluruh Anggota P3A & Warga Petani 4 Dusun"}]'::jsonb),
  ('surat', '[{"id":"sku","nama":"Surat Keterangan Usaha (SKU)","kategori":"Usaha & Ekonomi","kode":"470/SKU/TPK","lembaga_terkait":["bumdes","gapoktan"],"deskripsi":"Surat keterangan resmi dari Pemerintah Desa Timpik yang menyatakan bahwa pemohon benar-benar memiliki kegiatan usaha di wilayah Desa Timpik. Umumnya digunakan untuk pengajuan Kredit Usaha Rakyat (KUR), legalitas UMKM tani/ternak, atau bantuan modal usaha.","syarat":["Surat Pengantar dari Ketua RT dan RW setempat","Fotokopi KTP Elektronik pemohon","Fotokopi Kartu Keluarga (KK) pemohon","Foto dokumentasi tempat usaha / aktivitas usaha","Keterangan jenis usaha dan lama usaha berjalan"],"waktu_proses":"1 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_SKU/viewform","badge_color":"emerald"},{"id":"skd","nama":"Surat Keterangan Domisili (SKD)","kategori":"Kependudukan","kode":"470/SKD/TPK","lembaga_terkait":["ppdi","lpmd"],"deskripsi":"Surat yang menerangkan bahwa seseorang secara sah berdomisili dan bertempat tinggal di wilayah Desa Timpik, Kecamatan Susukan, baik sebagai penduduk tetap maupun penduduk sementara.","syarat":["Surat Pengantar Ketua RT & RW tempat berdomisili","Fotokopi KTP Elektronik & Kartu Keluarga (KK)","Surat pernyataan domisili bermaterai (bagi warga dari luar desa)","Pas foto berwarna 3x4 (1 lembar)"],"waktu_proses":"1 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_SKD/viewform","badge_color":"blue"},{"id":"skck","nama":"Surat Pengantar SKCK","kategori":"Izin & Rekomendasi","kode":"331/SKCK/TPK","lembaga_terkait":["babinsa-bhabinkamtibmas","satlinmas","karang-taruna"],"deskripsi":"Surat pengantar kelakuan baik dari Pemerintah Desa Timpik sebagai persyaratan utama penerbitan Surat Keterangan Catatan Kepolisian (SKCK) di Polsek Susukan atau Polres Semarang.","syarat":["Surat Pengantar dari Ketua RT & RW","Fotokopi KTP Elektronik dan Kartu Keluarga (KK)","Fotokopi Akta Kelahiran atau Ijazah Terakhir","Pas foto 4x6 latar belakang merah (2 lembar)"],"waktu_proses":"1 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_SKCK/viewform","badge_color":"purple"},{"id":"sktm","nama":"Surat Keterangan Tidak Mampu (SKTM)","kategori":"Kesejahteraan Sosial","kode":"401/SKTM/TPK","lembaga_terkait":["pkk","bpd"],"deskripsi":"Surat keterangan status sosial ekonomi untuk warga Desa Timpik yang membutuhkan rekomendasi beasiswa pendidikan (KIP-K/PIP), keringanan biaya perawatan medis rumah sakit, bantuan sosial, atau pengajuan bantuan hukum.","syarat":["Surat Pengantar RT/RW yang menerangkan kondisi ekonomi keluarga","Fotokopi KTP Kepala Keluarga & Kartu Keluarga (KK)","Foto kondisi rumah (tampak depan dan ruang dalam)","Surat pernyataan tidak mampu bermaterai 10.000","Kartu KIS/BPJS atau Kartu Bantuan Sosial (jika ada)"],"waktu_proses":"1 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_SKTM/viewform","badge_color":"amber"},{"id":"kematian","nama":"Surat Keterangan Kematian","kategori":"Kependudukan","kode":"472/KM/TPK","lembaga_terkait":["ppdi"],"deskripsi":"Surat pelaporan dan pencatatan peristiwa kematian warga untuk penerbitan Akta Kematian Disdukcapil, pengurusan klaim santunan/BPJS Ketenagakerjaan, hak waris, serta penutupan data kependudukan.","syarat":["Surat Keterangan Kematian dari RS / Dokter / Bidan / RT","KTP & KK asli almarhum/almarhumah","Fotokopi KTP pelapor (ahli waris / keluarga)","Fotokopi KTP dua orang saksi kematian"],"waktu_proses":"1 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_KEMATIAN/viewform","badge_color":"red"},{"id":"kelahiran","nama":"Surat Pengantar Akta Kelahiran","kategori":"Kependudukan","kode":"474/KL/TPK","lembaga_terkait":["pkk","kampung-kb","ppdi"],"deskripsi":"Surat pengantar bagi bayi yang baru lahir di Desa Timpik guna pendaftaran Nomor Induk Kependudukan (NIK) baru ke dalam Kartu Keluarga serta penerbitan Akta Kelahiran dari Dinas Kependudukan dan Catatan Sipil Kab. Semarang.","syarat":["Surat Keterangan Kelahiran dari Bidan / Rumah Sakit / Puskesmas","Fotokopi Buku Nikah / Akta Perkawinan orang tua (legalisir)","KTP Asli Suami dan Istri","Kartu Keluarga (KK) Asli orang tua","Fotokopi KTP dua orang saksi kelahiran"],"waktu_proses":"1 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_KELAHIRAN/viewform","badge_color":"blue"},{"id":"pindah","nama":"Surat Pengantar Pindah Penduduk (SKPWNI)","kategori":"Kependudukan","kode":"475/PND/TPK","lembaga_terkait":["ppdi","lpmd"],"deskripsi":"Surat pengantar perpindahan domisili warga Desa Timpik yang berpindah tempat tinggal ke desa lain, luar kecamatan, maupun luar kabupaten/provinsi.","syarat":["Surat Pengantar dari Ketua RT dan RW setempat","KTP Elektronik asli seluruh anggota keluarga yang pindah","Kartu Keluarga (KK) asli","Pas foto berwarna 3x4 (3 lembar) kepala keluarga","Alamat tujuan pindah lengkap (RT, RW, Desa, Kecamatan, Kab/Kota)"],"waktu_proses":"1-2 Hari Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_PINDAH/viewform","badge_color":"blue"},{"id":"izin-seni","nama":"Surat Izin Rekomendasi Pentas Seni & Keramaian","kategori":"Izin & Rekomendasi","kode":"300/IZN/TPK","lembaga_terkait":["pokdarwis","karang-taruna","babinsa-bhabinkamtibmas","satlinmas"],"deskripsi":"Surat izin dan rekomendasi kegiatan keramaian masyarakat atau pentas seni budaya (Wayang Orang Badoyo, Karawitan, Angguk, hajatan perkawinan) di wilayah Desa Timpik untuk diteruskan ke Forkopimcam Susukan, Babinsa, dan Bhabinkamtibmas.","syarat":["Surat permohonan tertulis ketua panitia / paguyuban seni / sohibul hajat","Fotokopi KTP Penanggung Jawab acara","Surat persetujuan lingkungan sekitar lokasi (diketahui Ketua RT/RW)","Susunan acara, jadwal waktu, dan estimasi jumlah pengunjung"],"waktu_proses":"1 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_IZIN_SENI/viewform","badge_color":"purple"},{"id":"beda-nama","nama":"Surat Keterangan Beda Identitas / Nama","kategori":"Kependudukan","kode":"470/BDN/TPK","lembaga_terkait":["ppdi","bpd"],"deskripsi":"Surat keterangan resmi yang menegaskan bahwa nama atau data tanggal lahir yang berbeda pada dua dokumen negara (misalnya antara KTP, KK, Ijazah, Buku Nikah, atau Paspor) adalah menunjuk pada orang yang sama.","syarat":["Surat Pengantar RT/RW","Fotokopi KTP & KK yang bersangkutan","Fotokopi dokumen yang memuat perbedaan data (Ijazah / Buku Nikah / Sertifikat)","Surat pernyataan beda nama bermaterai 10.000"],"waktu_proses":"1 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_BEDA_NAMA/viewform","badge_color":"blue"},{"id":"tanah","nama":"Surat Keterangan Penguasaan Fisik Tanah (Sporadik)","kategori":"Usaha & Ekonomi","kode":"590/TNH/TPK","lembaga_terkait":["gapoktan","p3a","ppdi"],"deskripsi":"Surat keterangan riwayat dan penguasaan fisik sebidang tanah pertanian atau pekarangan di Desa Timpik untuk kelengkapan berkas administrasi pertanahan atau pendaftaran sertifikat PTSL.","syarat":["Surat Pengantar RT/RW lokasi bidang tanah","Fotokopi SPPT PBB tahun berjalan yang lunas","Fotokopi KTP & KK pemohon / pemilik tanah","Bukti riwayat perolehan tanah (Letter C / Hibah / Jual Beli)","Surat pernyataan batas-batas tanah yang disetujui tetangga berbatasan"],"waktu_proses":"2 x 24 Jam Kerja","biaya":"Rp 0,- (Gratis)","link_gform":"https://docs.google.com/forms/d/e/1FAIpQLSc_PLACEHOLDER_TANAH/viewform","badge_color":"emerald"}]'::jsonb),
  ('kelembagaan', '[{"id":"bpd","nama":"Badan Permusyawaratan Desa (BPD)","singkatan":"BPD","kategori":"Pemerintahan & Pengawasan","dusun_terkait":"krajan","surat_terkait":["sktm","beda-nama"],"deskripsi":"Lembaga permusyawaratan dan perwakilan masyarakat desa yang menjalankan fungsi legislasi desa, menampung dan menyalurkan aspirasi masyarakat Desa Timpik, serta mengawasi kinerja Kepala Desa dan Pemerintah Desa.","fokus":["Legislasi Perdes","Penyerapan Aspirasi Warga","Pengawasan Anggaran Desa"]},{"id":"pkk","nama":"Tim Penggerak Pemberdayaan Kesejahteraan Keluarga","singkatan":"TP PKK","kategori":"Pemberdayaan Perempuan & Keluarga","dusun_terkait":"sumber","surat_terkait":["sktm","kelahiran"],"deskripsi":"Gerakan nasional pemberdayaan masyarakat yang berakar dari dan untuk keluarga demi terwujudnya keluarga Desa Timpik yang beriman, sehat, sejahtera, dan mandiri melalui 10 Program Pokok PKK.","fokus":["Kesehatan Ibu & Anak","Posyandu Balita & Lansia","Peningkatan Ekonomi Keluarga"]},{"id":"lpmd","nama":"Lembaga Pemberdayaan Masyarakat Desa","singkatan":"LPMD","kategori":"Pemberdayaan Masyarakat","dusun_terkait":"krajan","surat_terkait":["pindah","skd"],"deskripsi":"Wadah yang dibentuk atas prakarsa masyarakat sebagai mitra Pemerintah Desa Timpik dalam menampung dan mewujudkan aspirasi serta kebutuhan masyarakat di bidang pembangunan fisik dan sosial.","fokus":["Perencanaan Pembangunan","Gotong Royong Masyarakat","Pemeliharaan Infrastruktur Desa"]},{"id":"ppdi","nama":"Persatuan Perangkat Desa Indonesia","singkatan":"PPDI","kategori":"Aparatur Desa","dusun_terkait":"krajan","surat_terkait":["sku","skd","skck","kematian","kelahiran"],"deskripsi":"Organisasi profesi perhimpunan para perangkat desa yang bertugas memperkuat sinergi pelayanan birokrasi, tata kelola pemerintahan, dan pelayanan publik bagi seluruh warga Desa Timpik.","fokus":["Tata Kelola Birokrasi","Pelayanan Surat & Administrasi","Integritas Perangkat Desa"]},{"id":"karang-taruna","nama":"Karang Taruna \"Margo Ngudi Utomo\"","singkatan":"Margo Ngudi Utomo","kategori":"Kepemudaan & Olahraga","dusun_terkait":"krajan","surat_terkait":["skck","izin-seni"],"deskripsi":"Wadah pembinaan dan pengembangan generasi muda Desa Timpik untuk menumbuhkan kepedulian sosial, kreativitas kepemudaan, keolahragaan, serta pelestarian seni budaya lokal.","fokus":["Kegiatan Pemuda & Olahraga","Penggerak Acara Budaya","Kewirausahaan Pemuda"]},{"id":"satlinmas","nama":"Satuan Perlindungan Masyarakat","singkatan":"SATLINMAS","kategori":"Ketentraman & Ketertiban","dusun_terkait":"krajan","surat_terkait":["izin-seni","skck"],"deskripsi":"Satuan warga terlatih yang disiapkan untuk membantu penanggulangan bencana, menjaga keamanan lingkungan desa, ketentraman perhelatan warga, serta perlindungan masyarakat di wilayah Timpik.","fokus":["Ronda & Keamanan Lingkungan","Siaga Bencana Alam","Pengamanan Acara Desa"]},{"id":"bumdes","nama":"Badan Usaha Milik Desa \"Makmur\"","singkatan":"BUMDes Makmur","kategori":"Perekonomian Desa","dusun_terkait":"kencana","surat_terkait":["sku"],"deskripsi":"Badan usaha milik desa yang mengelola potensi ekonomi Desa Timpik, membuka unit usaha agraris, pengelolaan sarana desa, dan kemitraan guna mendongkrak Pendapatan Asli Desa (PADes).","fokus":["Pengelolaan Aset Desa","Distribusi Sarana Pertanian","Pemberdayaan UMKM Warga"]},{"id":"gapoktan","nama":"Gabungan Kelompok Tani \"Putri Kencana\"","singkatan":"GAPOKTAN Putri Kencana","kategori":"Pertanian & Agraris","dusun_terkait":"kencana","surat_terkait":["sku","tanah"],"deskripsi":"Wadah persatuan kelompok-kelompok tani di Desa Timpik untuk koordinasi pengadaan bibit unggul, pupuk bersubsidi, mekanisasi pertanian modern, serta peningkatan produktivitas hasil panen padi dan palawija.","fokus":["Distribusi Benih & Pupuk","Modernisasi Alat Pertanian","Ketahanan Pangan Agraris"]},{"id":"p3a","nama":"Perkumpulan Petani Pemakai Air \"Bogo Wastro\"","singkatan":"P3A Bogo Wastro","kategori":"Pengairan & Irigasi","dusun_terkait":"bogo","surat_terkait":["sku","tanah"],"deskripsi":"Organisasi pengelola jaringan irigasi persawahan di Desa Timpik yang mengatur tata pembagian debit air persawahan secara adil, pembersihan saluran irigasi tersier, dan konservasi sumber mata air.","fokus":["Pengaturan Debit Air Sawah","Normalisasi Saluran Irigasi","Konservasi Sumber Air"]},{"id":"pokdarwis","nama":"Kelompok Sadar Wisata","singkatan":"POKDARWIS","kategori":"Pariwisata & Budaya","dusun_terkait":"bogo","surat_terkait":["izin-seni"],"deskripsi":"Kelompok penggerak pariwisata yang bertugas mengidentifikasi dan mempromosikan potensi agrowisata pedesaan, wisata edukasi kesenian rakyat, serta keramahtamahan Sapta Pesona di Desa Timpik.","fokus":["Wisata Budaya & Edukasi","Promosi Potensi Kesenian","Sapta Pesona Lingkungan"]},{"id":"babinsa-bhabinkamtibmas","nama":"BABINSA & BHABINKAMTIBMAS","singkatan":"TNI - POLRI","kategori":"Keamanan & Pertahanan","dusun_terkait":"krajan","surat_terkait":["skck","izin-seni"],"deskripsi":"Unsur Pembina Desa dari Koramil 07/Susukan (Kodim 0714/Salatiga) dan Polsek Susukan (Polres Semarang) yang mendampingi warga dalam memelihara kondusifitas Kamtibmas dan pertahanan wilayah.","fokus":["Kamtibmas Wilayah","Penyelesaian Sengketa Warga","Penyuluhan Hukum"]},{"id":"perpustakaan","nama":"Perpustakaan Desa \"Sumber Ilmu\"","singkatan":"Sumber Ilmu","kategori":"Pendidikan & Literasi","dusun_terkait":"krajan","surat_terkait":["sktm"],"deskripsi":"Pusat sumber belajar dan ruang baca publik masyarakat Desa Timpik, menyediakan koleksi buku bacaan anak, literasi pertanian, buku keterampilan, dan sarana belajar santai bagi pelajar serta warga.","fokus":["Pojok Baca & Literasi Anak","Buku Panduan Pertanian","Edukasi Warga"]},{"id":"lpm-pangan","nama":"Lumbung Pangan Masyarakat \"Putri Kencana\"","singkatan":"LPM Putri Kencana","kategori":"Ketahanan Pangan","dusun_terkait":"kencana","surat_terkait":["sku"],"deskripsi":"Sarana penyimpanan dan pengelolaan cadangan pangan beras masyarakat Desa Timpik guna menjamin stabilitas pasokan pangan saat musim tanam dan antisipasi masa paceklik.","fokus":["Cadangan Pangan Beras","Stabilitas Harga Gabah","Ketahanan Pangan Darurat"]},{"id":"kampung-kb","nama":"Kampung KB \"Putri Mandiri\"","singkatan":"Kampung KB","kategori":"Kependudukan & Keluarga","dusun_terkait":"sumber","surat_terkait":["kelahiran","sktm"],"deskripsi":"Satuan wilayah tingkat desa yang mengintegrasikan program kependudukan, keluarga berencana, pembangunan keluarga, dan pembangunan sektor terkait untuk mewujudkan keluarga berkualitas.","fokus":["Pencegahan Stunting","Keluarga Berencana","Ketahanan Lansia & Remaja"]}]'::jsonb),
  ('potensi', '{"agraris":{"judul":"Potensi Sektor Agraris & Pertanian","deskripsi":"Desa Timpik memiliki bentang alam subur seluas ± 243 Hektar dengan komoditas pertanian unggulan yang menjadi penopang ekonomi mayoritas warga.","luas_wilayah":"± 243 Hektar","mayoritas_mata_pencaharian":"Petani & Peternak (78%)","komoditas_utama":[{"nama":"Padi Sawah Berkualitas","deskripsi":"Sistem persawahan irigasi teknis yang dikelola oleh P3A Bogo Wastro dan GAPOKTAN Putri Kencana dengan produktivitas tinggi.","icon":"wheat"},{"nama":"Palawija & Hortikultura","deskripsi":"Jagung, cabai, kacang tanah, dan sayuran segar yang mengisi masa rotasi tanam secara produktif.","icon":"sprout"},{"nama":"Perkebunan & Buah Rakyat","deskripsi":"Kelapa, pisang, dan aneka tanaman kebun produktif yang menghiasi pekarangan dan bukit desa.","icon":"tree"},{"nama":"Lumbung Pangan Putri Kencana","deskripsi":"Sistem ketahanan pangan mandiri untuk mengamankan stok beras warga dan menstabilkan harga pasca panen.","icon":"warehouse"}]},"kebudayaan":{"judul":"Potensi Seni, Tradisi & Kebudayaan","deskripsi":"Kekayaan tradisi adiluhung yang tetap hidup, diwariskan lintas generasi dari anak-anak, pemuda, hingga para sesepuh desa.","kesenian":[{"nama":"Wayang Orang (Badoyo) Dusun Bogo","lokasi":"Dusun Bogo, Desa Timpik","deskripsi":"Kesenian teater tradisional Jawa yang memadukan tarian, dialog tembang, dan lakon pewayangan epik Mahabarata & Ramayana. Menjadi kebanggaan budaya Desa Timpik yang diakui di wilayah Kecamatan Susukan.","keunikan":"Dimainkan oleh para seniman warga Dusun Bogo dengan kostum wayang lengkap dan tata rias khas tradisional."},{"nama":"Seni Karawitan Jawa (Sekar Melati & Wedotomo)","lokasi":"Desa Timpik","deskripsi":"Ansambel gamelan Jawa laras pelog dan slendro yang aktif dilestarikan oleh paguyuban Sekar Melati dan Wedotomo. Melibatkan berbagai generasi warga dari tingkat sekolah dasar hingga kaum lansia.","keunikan":"Harmonisasi gending-gending klasik dan kreasi kontemporer pengiring upacara adat serta perhelatan budaya."},{"nama":"Kesenian Angguk (Angguk Alhidayah)","lokasi":"Dusun Sumber, Desa Timpik","deskripsi":"Seni tari bernafaskan Islami yang dipadukan dengan syair-syair puji-pujian dan rebana, ditarikan secara serentak penuh penghayatan spiritual dan kekompakan.","keunikan":"Harmoni antara dakwah kultural dan pelestarian seni gerak tradisional."},{"nama":"Tradisi Merti Dusun / Sedekah Bumi","lokasi":"Seluruh Dusun Desa Timpik","deskripsi":"Ungkapan rasa syukur bersama seluruh warga tani kepada Tuhan Yang Maha Esa atas kelimpahan hasil bumi, air yang mengalir, dan kerukunan warga.","keunikan":"Arak-arakan gunungan hasil panen, doa bersama di pendopo balai desa, dan pertunjukan wayang semalam suntuk."}]}}'::jsonb),
